import std.concurrent as conc
import std.test as st
import std.time

test "order" {
    let ch: conc.Channel<Int64> = conc.channel(0)
    scope {
        let a = task effect net time {
            let _ = time.sleep(10)
            ch.send(1)
        }
        let b = task effect net time {
            let _ = time.sleep(10)
            ch.send(2)
        }
        advanceTime(10)
        let first = ch.receive()
        let second = ch.receive()
        match first {
            Some(x) => { st.assertEqual(x, 1) }
            None => { assert(false, "none-first") }
        }
        match second {
            Some(y) => { st.assertEqual(y, 2) }
            None => { assert(false, "none-second") }
        }
        let _ = a.await()
        let _ = b.await()
    }
    assert(true, "done")
}
